INSERT INTO "Question" ("id","prompt","options","correctIndex","explanation","difficulty","answers","hint","order","courseId","levelId","createdAt") VALUES
('q_cj-7-rozsirene-vetne-cleny_0','Který větný člen říká, co někdo dělá?',ARRAY['podmět','přívlastek','předmět','přísudek']::TEXT[],3,'Přísudek je obvykle sloveso.',1,ARRAY[]::TEXT[],NULL,0,'c_cj-7-rozsirene-vetne-cleny',NULL,NOW()),
('q_cj-7-rozsirene-vetne-cleny_1','Který větný člen odpovídá na otázku kdo, co + sloveso?',ARRAY['podmět','přísudek','příslovečné určení','předmět']::TEXT[],0,'Podmět je ten, kdo koná děj.',1,ARRAY[]::TEXT[],NULL,1,'c_cj-7-rozsirene-vetne-cleny',NULL,NOW()),
('q_cj-7-rozsirene-vetne-cleny_2','Ve větě Malý pes štěká je přívlastek:',ARRAY['pes','žádný','malý','štěká']::TEXT[],2,'Přívlastek popisuje podstatné jméno.',1,ARRAY[]::TEXT[],NULL,2,'c_cj-7-rozsirene-vetne-cleny',NULL,NOW()),
('q_cj-7-rozsirene-vetne-cleny_3','Na jakou otázku odpovídá přívlastek?',ARRAY['koho, co','kdo, co','kde, kdy, jak','jaký, který, čí']::TEXT[],3,'Přívlastek se ptá na vlastnost.',2,ARRAY[]::TEXT[],NULL,3,'c_cj-7-rozsirene-vetne-cleny',NULL,NOW()),
('q_cj-7-rozsirene-vetne-cleny_4','Ve větě Čtu knihu je předmět:',ARRAY['knihu','čtu','čtu knihu','žádný']::TEXT[],0,'Čtu koho, co? Knihu.',2,ARRAY[]::TEXT[],NULL,4,'c_cj-7-rozsirene-vetne-cleny',NULL,NOW()),
('q_cj-7-rozsirene-vetne-cleny_5','Ve větě Včera pršelo je příslovečné určení:',ARRAY['pršelo','žádné','včera','pršelo včera']::TEXT[],2,'Včera = kdy?',2,ARRAY[]::TEXT[],NULL,5,'c_cj-7-rozsirene-vetne-cleny',NULL,NOW()),
('q_cj-7-rozsirene-vetne-cleny_6','Ve větě Žák píše domácí úkol pečlivě je příslovečné určení způsobu:',ARRAY['úkol','pečlivě','píše','domácí']::TEXT[],1,'Píše jak? Pečlivě.',3,ARRAY[]::TEXT[],NULL,6,'c_cj-7-rozsirene-vetne-cleny',NULL,NOW()),
('q_cj-7-rozsirene-vetne-cleny_7','Ve větě Babička ze vsi přijela je přívlastek:',ARRAY['žádný','přijela','ze vsi','babička']::TEXT[],2,'Která babička? Ze vsi.',3,ARRAY[]::TEXT[],NULL,7,'c_cj-7-rozsirene-vetne-cleny',NULL,NOW()),
('q_cj-7-rozsirene-vetne-cleny_8','Ve větě Dal jsem Petrovi dárek je předmět Petrovi ve:',ARRAY['2. pádě','4. pádě','3. pádě','1. pádě']::TEXT[],2,'Komu? Petrovi.',3,ARRAY[]::TEXT[],NULL,8,'c_cj-7-rozsirene-vetne-cleny',NULL,NOW()),
('q_cj-7-rozsirene-vetne-cleny_9','Který druh přívlastku je ve spojení kniha pro děti?',ARRAY['volný','shodný','těsný','neshodný']::TEXT[],3,'Neshodný přívlastek stojí v jiném pádě než jádro.',4,ARRAY[]::TEXT[],NULL,9,'c_cj-7-rozsirene-vetne-cleny',NULL,NOW()),
('q_cj-7-rozsirene-vetne-cleny_10','Který přívlastek je shodný?',ARRAY['hrnec s ouškem','dům u lesa','cesta do školy','červené jablko']::TEXT[],3,'Shodný přívlastek se shoduje v rodě, čísle a pádě.',4,ARRAY[]::TEXT[],NULL,10,'c_cj-7-rozsirene-vetne-cleny',NULL,NOW()),
('q_cj-7-rozsirene-vetne-cleny_11','Příslovečné určení místa je ve větě:',ARRAY['Hrajeme hlasitě.','Hrajeme celý den.','Hrajeme na hřišti.','Hrajeme pro radost.']::TEXT[],2,'Kde? Na hřišti.',4,ARRAY[]::TEXT[],NULL,11,'c_cj-7-rozsirene-vetne-cleny',NULL,NOW()),
('q_cj-7-rozsirene-vetne-cleny_12','V jaké větě je podmět nevyjádřený?',ARRAY['Čteme knihu.','Kniha leží na stole.','Žáci čtou knihu.','Já čtu knihu.']::TEXT[],0,'Podmět my se z koncovky pozná.',5,ARRAY[]::TEXT[],NULL,12,'c_cj-7-rozsirene-vetne-cleny',NULL,NOW()),
('q_cj-7-rozsirene-vetne-cleny_13','Příslovečné určení příčiny je ve větě:',ARRAY['Usnul včera.','Usnul hluboce.','Z únavy usnul u televize.','Usnul u televize.']::TEXT[],2,'Proč? Z únavy.',5,ARRAY[]::TEXT[],NULL,13,'c_cj-7-rozsirene-vetne-cleny',NULL,NOW()),
('q_cj-7-rozsirene-vetne-cleny_14','Ve které větě je rozvitý podmět?',ARRAY['Starý pes štěká.','Štěká.','Prší.','Pes štěká.']::TEXT[],0,'Podmět pes je rozvitý přívlastkem starý.',5,ARRAY[]::TEXT[],NULL,14,'c_cj-7-rozsirene-vetne-cleny',NULL,NOW()),
('q_cj-7-slovotvorba-stavba_0','Co je kořen slova?',ARRAY['předpona','koncovka','část slova nesoucí základní význam','přípona']::TEXT[],2,'Kořen je společný příbuzným slovům.',1,ARRAY[]::TEXT[],NULL,0,'c_cj-7-slovotvorba-stavba',NULL,NOW()),
